REQUIRED = ["title", "impact", "evidence", "fix", "owner", "due"]
VAGUE = {"may", "possibly", "various", "appropriate"}

def lint(finding):
    problems = []
    for field in REQUIRED:
        if not finding.get(field):
            problems.append("missing " + field)
    if len(finding.get("title", "").split()) < 5:
        problems.append("title too short to say what and where")
    words = set(finding.get("impact", "").lower().replace(".", "").split())
    for w in sorted(VAGUE & words):
        problems.append("vague impact: " + w)
    return problems or ["ok"]

draft = {"title": "XSS vulnerability",
         "impact": "An attacker may do various things.",
         "evidence": "see screenshot"}
print(lint(draft))

rewrite = {"title": "Stored XSS in support-ticket subject runs in agents' sessions",
