print(lint(rewrite))

# Sherman Kent's five middle bands: (word, centre %, give or take %)
BANDS = [("almost certain", 93, 6), ("probable", 75, 12),
         ("chances about even", 50, 10), ("probably not", 30, 10),
         ("almost certainly not", 7, 5)]

def words_for(p):
    for word, centre, spread in BANDS:
        if centre - spread <= p <= centre + spread:
            return f"{p}%: '{word}' ({centre - spread}-{centre + spread}%)"
    return f"{p}%: no band fits, state the number"

for p in (90, 65, 35, 15, 61):
    print(words_for(p))

from statistics import median

# days from report to verified fix, for findings closed this quarter
closed = {"critical": [3, 9, 14, 30, 41],
          "high": [12, 20, 25, 33, 60, 75, 90]}
target = {"critical": 15, "high": 30}

for sev, days in closed.items():
    ok = sum(d <= target[sev] for d in days)
    print(f"{sev:<8} median {median(days):>3} days; "
          f"{ok}/{len(days)} inside the {target[sev]}-day target "
          f"({100 * ok / len(days):.0f}%)")
